glob typographyVariantsConfig: dict[str, object] = {
    "base": "text-foreground",
    "variants": {
        "variant": {
            "h1": "scroll-m-20 text-4xl font-extrabold tracking-tight lg:text-5xl",
            "h2": "scroll-m-20 pb-2 text-3xl font-semibold tracking-tight first:mt-0",
            "h3": "scroll-m-20 text-2xl font-semibold tracking-tight",
            "h4": "scroll-m-20 text-xl font-semibold tracking-tight",
            "h5": "scroll-m-20 text-lg font-semibold tracking-tight",
            "h6": "scroll-m-20 text-base font-semibold tracking-tight",
            "p": "leading-7 [&:not(:first-child)]:mt-6",
        },
        "affects": {
            "default": "",
            "lead": "text-xl text-muted-foreground",
            "large": "text-lg font-semibold",
            "small": "text-sm font-medium leading-none",
            "muted": "text-sm text-muted-foreground",
            "withoutPMargin": "[&:not(:first-child)]:mt-0",
        },
    },
    "defaultVariants": {
        "variant": "h1",
        "affects": "default",
    },
};

def:pub typographyVariants(variant: str | None = None, affects: str | None = None, className: str | None = None) -> str {
    defaults = typographyVariantsConfig["defaultVariants"] as dict[str, str];
    resolved_variant = variant if variant is not None else defaults["variant"];
    resolved_affects = affects if affects is not None else defaults["affects"];
    base = typographyVariantsConfig["base"] as str;
    variant_map = (typographyVariantsConfig["variants"] as dict[str, dict[str, str]])["variant"];
    affects_map = (typographyVariantsConfig["variants"] as dict[str, dict[str, str]])["affects"];
    return cn(base, variant_map[resolved_variant], affects_map[resolved_affects], className) as str;
}

def:pub Typography(props: dict[str, object]) -> JsxElement {
    className_val = props.get("className") as str | None;
    variant_val = props.get("variant", "h1") as str;
    affects_val = props.get("affects", "default") as str;
    rest: dict[str, object] = {k: v for (k, v) in props.items() if k not in ["className", "variant", "affects"]};
    as_ = variant_val if variant_val else "h1";
    <@as_ {**rest} className={typographyVariants(variant=variant_val, affects=affects_val, className=className_val)} />
}

