def:pub humanizeKey(key: str) -> str {
    result = re.sub(r"([a-z])([A-Z])", r"\1 \2", key);
    result = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1 \2", result);
    if result {
        return result[0].upper() + result[1:];
    }
    return result;
}

