            onChange(f"rgba({rgb['r']}, {rgb['g']}, {rgb['b']}, {alpha})");
        }
    }

    overlay = (
        <SketchPicker
            color={color}
            className="color-picker-overlay"
            onChangeComplete={onColorChange}
            presetColors={DEFAULT_COLORS}
        />
    );

    <Dropdown overlay={overlay} trigger={["click", "hover"]} disabled={not canChangeColor}>
        <div className={cx("color-picker", className)} style={style}>
            <div className="color-picker-swatch" style={{"backgroundColor": color}} />
        </div>
    </Dropdown>
}

