import from "react" { useEffect }

def:pub useClickOutside(ref: object, onClickOutside: Callable[[], None]) {
    useEffect(lambda {
        def handle_click_outside(event: MouseEvent) {
            if ref?.current?.contains(event.target as object) is False {
                onClickOutside();
            }
        }
        document.addEventListener("mouseup", handle_click_outside);
        return lambda {
            document.removeEventListener("mouseup", handle_click_outside);
        };
    }, [ref, onClickOutside]);
}

