import from "@/shared/components/ChunkErrorBoundary" { isChunkLoadError }
import from "@/shared/components/VersionWatcher" { hardReload }
import from "@/shared/lib/error" { sanitizeError, logError }
import from "@/shared/ui/button" { Button }

def:pub Error(error: dict, reset: Callable[[], None]) -> JsxElement {
    isStaleChunk = isChunkLoadError(error);
    safe = sanitizeError(error);

    useEffect(lambda {
        digest = error["digest"] if "digest" in error else None;
        logError("RouteError", error, {"digest": digest});
        if isStaleChunk {
            FLAG = "nosion:chunk-reloaded-at";
            try {
                last = int(sessionStorage.getItem(FLAG) or "0");
                if Date.now() - last > 60000 {
                    sessionStorage.setItem(FLAG, str(Date.now()));
                    hardReload();
                }
            } except Exception {
                hardReload();
            }
        }
    }, [error, isStaleChunk]);

    if isStaleChunk {
        return (
            <div className="min-h-screen flex items-center justify-center p-6 bg-background">
                <div className="max-w-md w-full rounded-lg border border-border bg-card p-6 text-center">
                    <div className="text-3xl mb-2">🔄</div>
                    <h2 className="text-base font-semibold mb-1">Update available</h2>
                    <p className="text-sm text-muted-foreground mb-4">
                        The app was updated while you were here. Reloading…
                    </p>
                    <Button
                        onClick={hardReload}
                        className="h-auto rounded-md bg-foreground px-3 py-1.5 text-sm text-background hover:bg-foreground hover:opacity-90"
                    >
                        Reload now
                    </Button>
                </div>
            </div>
        );
    }

    <div className="min-h-screen flex items-center justify-center p-6 bg-background">
        <div className="max-w-md w-full rounded-lg border border-destructive/30 bg-destructive/5 p-6 text-center">
            <div className="flex justify-center mb-3">
                <div className="rounded-full bg-destructive/10 p-3">
                    <AlertTriangle className="h-6 w-6 text-destructive" />
                </div>
            </div>
            <h2 className="text-lg font-semibold text-foreground mb-1">Something went wrong</h2>
            <p className="text-sm text-muted-foreground mb-4">{safe["message"]}</p>
            {if "digest" in error and error["digest"] {
                <p className="text-xs text-muted-foreground/70 mb-4 font-mono">id: {error["digest"]}</p>
            }}
            <div className="flex justify-center gap-2">
                <Button
                    onClick={reset}
                    className="h-auto gap-1.5 rounded-md bg-foreground px-3 py-1.5 text-sm text-background hover:bg-foreground hover:opacity-90 [&_svg]:size-3.5"
                >
                    <RefreshCw className="h-3.5 w-3.5" /> Try again
                </Button>
                <Button
                    variant="outline"
                    onClick={hardReload}
                    className="h-auto rounded-md px-3 py-1.5 text-sm font-normal"
                >
                    Hard reload
                </Button>
            </div>
        </div>
    </div>
}

