# from: DaniloNovakovic__chrome-dynamic-bookmarks::background/createObservable.ts
type ObservableCallback = Callable[[object], None];

obj Observable {
    has observers: dict[str, ObservableCallback] = {};

    def subscribe(key: str, callback: ObservableCallback) {
        self.observers[key] = callback;
    }

    def unsubscribe(key: str) {
        del self.observers[key];
    }

    def notify(event: object) {
        for observer in self.observers.values() {
            observer(event);
        }
    }
}

def:pub createObservable() -> Observable {
    return Observable();
}

