# from: BjornMelin__bjornmelin-platform-io::lib/agent-skills/filtering.ts
import from "@/lib/projects/filtering" { normalizeText }

type AgentSkillCardModel = dict[str, object];
type AgentSkillFilters = dict[str, str];

glob readinessLabelsSet: set[str] = {"Valid", "Packaged", "Documented", "Resource-rich", "Emerging"};

def isAgentSkillReadinessLabel(value: str) -> bool {
    return value in readinessLabelsSet;
}

def skillSearchText(skill: AgentSkillCardModel) -> str {
    return " ".join([
        skill["name"] as str,
        skill["description"] as str,
        skill["category"] as str,
        skill["path"] as str,
        " ".join(skill["readinessLabels"] as list[str]),
        " ".join(skill["qualitySignals"] as list[str]),
        " ".join(skill["improvementSignals"] as list[str]),
    ]);
}

def:pub filterAgentSkills(skills: list[AgentSkillCardModel], filters: AgentSkillFilters) -> list[AgentSkillCardModel] {
    q = normalizeText(filters["q"]);
    hasQuery = len(q) > 0;
    readiness: str | None = None;
    if filters["readiness"] != "all" and isAgentSkillReadinessLabel(filters["readiness"]) {
        readiness = filters["readiness"];
    }
    result: list[AgentSkillCardModel] = [];
    for skill in skills {
        if filters["category"] != "all" and skill["category"] as str != filters["category"] { continue; }
        if readiness is not None and readiness not in (skill["readinessLabels"] as list[str]) { continue; }
        packageStatus = skill["packageStatus"] as dict[str, bool];
        if filters["packageState"] == "packaged" and not packageStatus["present"] { continue; }
        if filters["packageState"] == "source" and packageStatus["present"] { continue; }
        if not hasQuery { result.append(skill); continue; }
        if q in normalizeText(skillSearchText(skill)) { result.append(skill); }
    }
    return result;
}

def:pub sortAgentSkills(skills: list[AgentSkillCardModel], sort: str) -> list[AgentSkillCardModel] {
    sorted = [*skills];
    if sort == "featured" {
        sorted.sort(key=lambda (s: AgentSkillCardModel) { return (-int(s["featured"] as bool), -(s["score"] as float), (s["name"] as str).lower()); });
    } elif sort == "resources" {
        sorted.sort(key=lambda (s: AgentSkillCardModel) { resources = s["resources"] as dict[str, int]; return (-resources["total"], -(s["score"] as float)); });
    } elif sort == "packaged" {
        sorted.sort(key=lambda (s: AgentSkillCardModel) { packageStatus = s["packageStatus"] as dict[str, bool]; return (-int(packageStatus["present"]), -(s["score"] as float)); });
    } else {
        sorted.sort(key=lambda (s: AgentSkillCardModel) { return (s["name"] as str).lower(); });
    }
    return sorted;
}

