import from "../services/storage" { getFromStorage, saveToStorage }

glob VIDEO_STREAM_KEY = "TWILIO:VS";
glob AUDIO_STREAM_KEY = "TWILIO:AS";

type SaveSettingFn = Callable[[bool], None];
type GetSettingFn = Callable[[], bool];

type TrackSettings = dict[
    str,
    SaveSettingFn | GetSettingFn,
];

def:pub useTracksSettings() -> TrackSettings {
    def save_audio_settings(is_enabled: bool) {
        saveToStorage(AUDIO_STREAM_KEY, is_enabled);
    }

    def save_video_settings(is_enabled: bool) {
        saveToStorage(VIDEO_STREAM_KEY, is_enabled);
    }

    def get_audio_settings() -> bool {
        stored = getFromStorage(AUDIO_STREAM_KEY);
        if stored is not None {
            return stored as bool;
        }
        return True;
    }

    def get_video_settings() -> bool {
        stored = getFromStorage(VIDEO_STREAM_KEY);
        if stored is not None {
            return stored as bool;
        }
        return True;
    }

    return {
        "saveAudioSettings": save_audio_settings,
        "saveVideoSettings": save_video_settings,
        "getAudioSettings": get_audio_settings,
        "getVideoSettings": get_video_settings,
    };
}

