# from: jhasuraj01__filepad::presentation/components/counter/Counter.tsx
def:pub Counter() -> JsxElement {
    has count: int = 0;
    has incrementAmount: str = "2";

    def get_increment_value() -> int {
        try {
            return int(incrementAmount);
        } except ValueError {
            return 0;
        }
    }

    def handle_decrement(e: MouseEvent) {
        count = count - 1;
    }

    def handle_increment(e: MouseEvent) {
        count = count + 1;
    }

    def handle_amount_change(e: ChangeEvent) {
        incrementAmount = e.target.value;
    }

    def handle_add_amount(e: MouseEvent) {
        count = count + get_increment_value();
    }

    async def handle_add_async(e: MouseEvent) {
        count = count + get_increment_value();
    }

    def handle_add_if_odd(e: MouseEvent) {
        if count % 2 != 0 {
            count = count + get_increment_value();
        }
    }

    <div>
        <div className="row">
            <button className="button" aria-label="Decrement value" onClick={handle_decrement}>-</button>
            <span className="value">{count}</span>
            <button className="button" aria-label="Increment value" onClick={handle_increment}>+</button>
        </div>
        <div className="row">
            <input className="textbox" aria-label="Set increment amount" value={incrementAmount} onChange={handle_amount_change} />
            <button className="button" onClick={handle_add_amount}>Add Amount</button>
            <button className="asyncButton" onClick={handle_add_async}>Add Async</button>
            <button className="button" onClick={handle_add_if_odd}>Add If Odd</button>
        </div>
    </div>
}

