import from "react-dom" { createPortal }

glob COLLECTION_SELECTOR = "[id*=\"collection-item-container\"], .collection-item-container";

def getCollectionTargets() -> list[dict[str, str | HTMLElement]] {
    elements = document.querySelectorAll(COLLECTION_SELECTOR) as list[HTMLElement];
    targets: list[dict[str, str | HTMLElement]] = [];
    for element in elements {
        tralbumId = element.getAttribute("data-tralbumid");
        if not tralbumId {
            continue;
        }
        if not element.querySelector(".redownload-item") {
            continue;
        }
        targets.append({"id": tralbumId, "host": element});
    }
    return targets;
}

glob PURCHASES_ITEM_SELECTOR = ".purchases-item";

glob PURCHASES_LINKS_SELECTOR = "[data-tid=\"links\"]";

def getPurchasesTargets() -> list[dict[str, str | HTMLElement]] {
    items = document.querySelectorAll(PURCHASES_ITEM_SELECTOR) as list[HTMLElement];
    targets: list[dict[str, str | HTMLElement]] = [];
    for item in items {
        id = item.getAttribute("sale_item_id");
        if not id {
            continue;
        }
        links = item.querySelector(PURCHASES_LINKS_SELECTOR) as HTMLElement | None;
        if not links {
            continue;
        }
        mount = links.querySelector(f"[data-band-play-batch-checkbox-mount=\"{id}\"]") as HTMLElement | None;
        if not mount {
            continue;
        }
        targets.append({"id": id, "mount": mount});
    }
    return targets;
}

def:pub BatchDownloadCheckboxesLayer(
    page: str | None,
    checkboxClass: str,
    onCheckboxClick: Callable[[str, HTMLInputElement, bool, bool], None]
) -> JsxElement {
    if not page {
        return <></>;
    }
    if page == "collection" {
        targets = getCollectionTargets();
        return <>
            {for target in targets {
                tid = target["id"] as str;
                host = target["host"] as HTMLElement;
                createPortal(
                    <input
                        type="checkbox"
                        className={checkboxClass}
                        data-band-play-batch-checkbox="true"
                        data-band-play-batch-id={tid}
                        style={{"position": "absolute", "left": "9px", "top": "9px"}}
                        onClick={lambda (e: MouseEvent) {
                            input = e.currentTarget as HTMLInputElement;
                            onCheckboxClick(tid, input, e.shiftKey, e.metaKey);
                        }}
                    />,
                    host,
                    tid
                );
            }}
        </>;
    }
    targets = getPurchasesTargets();
    return <>
        {for target in targets {
            tid = target["id"] as str;
            mount = target["mount"] as HTMLElement;
            createPortal(
                <input
                    type="checkbox"
                    className={checkboxClass}
                    data-band-play-batch-checkbox="true"
                    data-band-play-batch-id={tid}
                    onClick={lambda (e: MouseEvent) {
                        input = e.currentTarget as HTMLInputElement;
                        onCheckboxClick(tid, input, e.shiftKey, e.metaKey);
                    }}
                />,
                mount,
                tid
            );
        }}
    </>;
}

