def:pub getVarianceStatus(varianceDays: float | None) -> any {
    if (varianceDays == None) {
        return "on-track";
    }
    threshold = 1;
    if (varianceDays > threshold) {
        return "ahead";
    }
    if (varianceDays < -threshold) {
        return "behind";
    }
    return "on-track";
}

def:pub getBaselineTask(baseline: any | None, taskId: str) -> any | None {
    if not baseline {
        return undefined;
    }
    return baseline.tasks.find(lambda (t: any) -> any { return (t.id == taskId); });
}

