# language: jac
# from: travisjneuman__neumanos::hooks/useOfflineStatus.ts
import from "react" { useEffect, useState, useRef }

def:pub useOfflineStatus() -> dict[str, bool] {
    onlineState = useState(navigator.onLine);
    isOnline = onlineState[0];
    setIsOnline = onlineState[1];
    wasOfflineRef = useRef(False);
    reconnectedState = useState(False);
    showReconnected = reconnectedState[0];
    setShowReconnected = reconnectedState[1];
    timerRef = useRef(None);
    useEffect(lambda {
        def handleOnline() {
            setIsOnline(True);
            if wasOfflineRef.current {
                setShowReconnected(True);
                if timerRef.current {
                    clearTimeout(timerRef.current);
                }
                timerRef.current = setTimeout(lambda {
                    setShowReconnected(False);
                    timerRef.current = None;
                }, 3000);
            }
        }
        def handleOffline() {
            setIsOnline(False);
            wasOfflineRef.current = True;
            setShowReconnected(False);
            if timerRef.current {
                clearTimeout(timerRef.current);
                timerRef.current = None;
            }
        }
        window.addEventListener("online", handleOnline);
        window.addEventListener("offline", handleOffline);
        return lambda {
            window.removeEventListener("online", handleOnline);
            window.removeEventListener("offline", handleOffline);
            if timerRef.current {
                clearTimeout(timerRef.current);
            }
        };
    }, []);
    return {"isOnline": isOnline, "isOffline": not isOnline, "showReconnected": showReconnected};
}

