def:pub convertTimeStringToSeconds(value: str) -> float {
    if notExist(value) {
        return 0;
    }
    parts = value.split(":");
    if (len(parts) < 2) {
        return 0;
    }
    minutes = parseInt(parts[0], 10);
    seconds = parseInt(parts[1], 10);
    return ((minutes * 60) + seconds);
}

