def:pub summarizeChannelAccounts(accounts: list[dict[str, bool]]) -> dict[str, int] {
    connected = 0;
    configured = 0;
    enabled = 0;
    for account in accounts {
        if account["configured"] {
            configured += 1;
        }
        if account["enabled"] {
            enabled += 1;
        }
    }
    return {"total": len(accounts), "connected": connected, "configured": configured, "enabled": enabled};
}

