        return {"required": True, "message": msg or "请输入"};
    }

    static def selectRequired(msg: str | None = None) -> dict[str, object] {
        return {"required": True, "message": msg or "请选择"};
    }

    static def idNumber(msg: str | None = None) -> dict[str, object] {
        return {"pattern": r"^(\d{17}[\dxX])|\d{15}$", "message": msg or "证件号码格式不正确"};
    }

    static def phoneNumber(msg: str | None = None) -> dict[str, object] {
        return {"pattern": r"^1\d{10}$", "message": msg or "手机号格式不正确"};
    }

    static def contactNumber(msg: str | None = None) -> dict[str, object] {
        return {"pattern": r"^[\d-]{7,20}$", "message": msg or "联系方式格式不正确"};
    }

    static def bankNumber(msg: str | None = None) -> dict[str, object] {
        return {"pattern": r"\d{1,19}$", "message": msg or "银行账号格式不正确"};
    }
}

