def:pub SubscriptionButton(isPro: bool) -> JsxElement {
    proModal = useProModal();
    actionHook = useAction(stripeRedirect, {"onSuccess": lambda (data: str) { window.location.href = data; }, "onError": lambda (error: str) { toast.error(error); }});
    execute = actionHook.execute;
    isLoading = actionHook.isLoading;
    def onClick {
        if isPro {
            execute({});
        } else {
            proModal.onOpen();
        }
    }
    return <Button variant="primary" onClick={onClick} disabled={isLoading}>{("Manage subscription" if isPro else "Upgrade to pro")}</Button>;
}

