import from "react" { useEffect }

def:pub Modal(open: bool, onClose: Callable[[], None], title: str, children: object = None) -> JsxElement | None {
    useEffect(lambda {
        if not open {
            return lambda { };
        }
        def on_key(e: KeyboardEvent) {
            if e.key == "Escape" {
                onClose();
            }
        }
        document.addEventListener("keydown", on_key);
        return lambda { document.removeEventListener("keydown", on_key); };
    }, [open, onClose]);

    useEffect(lambda {
        document.body.style.overflow = "hidden" if open else "";
        return lambda { document.body.style.overflow = ""; };
    }, [open]);

    if not open {
        return None;
    }

    def handle_overlay_click(e: MouseEvent) {
        onClose();
    }

    def handle_content_click(e: MouseEvent) {
        e.stopPropagation();
    }

    <div
        className="fixed inset-0 z-[100] flex items-start justify-center"
        style={{"background": "oklch(0% 0 0 / 0.45)", "backdropFilter": "blur(4px)", "overflowY": "auto", "padding": "2rem 1rem"}}
        onClick={handle_overlay_click}
    >
        <div
            className="relative w-full max-w-2xl rounded-2xl border border-[var(--line)] shadow-[var(--shadow-lg)]"
            style={{"background": "var(--bg-1)"}}
            onClick={handle_content_click}
        >
            <div
                className="flex items-center justify-between px-6 py-4 border-b border-[var(--line)]"
                style={{"background": "var(--bg-2)", "borderRadius": "1rem 1rem 0 0"}}
            >
                <h2
                    className="text-xl"
                    style={{"fontFamily": "Instrument Serif, Georgia, serif", "color": "var(--ink)"}}
                >
                    {title}
                </h2>
                <button
                    onClick={onClose}
                    aria-label="Close"
                    className="w-8 h-8 flex items-center justify-center rounded-lg transition-colors hover:bg-[var(--bg-3)]"
                    style={{"color": "var(--ink-4)"}}
                >
                    <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
                        <path d="M1 1l12 12M13 1L1 13" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
                    </svg>
                </button>
            </div>
            <div className="px-6 py-6">
                {children}
            </div>
        </div>
    </div>
}

