def:pub Space(
    gap: int | str = "middle",
    direction: str = "horizontal",
    justify: str = "start",
    align: str = "stretch",
    bgColor: str = "",
    className: str = "",
    style: dict[str, object] | None = None,
    children: object | None = None,
) -> JsxElement {
    gap_cls = gapClass[gap] if isinstance(gap, str) else None;
    merged_style: dict[str, object] = {**(style if style else {})};
    if isinstance(gap, int) {
        merged_style["gap"] = f"{gap}px";
    }
    if bgColor {
        merged_style["backgroundColor"] = bgColor;
    }
    return (
        <div
            className={classNames(
                "flex flex-wrap items-center",
                {"flex-col": direction == "vertical"},
                justifyClass[justify if justify else "start"],
                alignClass[align if align else "stretch"],
                gap_cls,
                className,
            )}
            style={merged_style}
        >
            {children}
        </div>
    );
}

