def centered(triggerRect: any, tooltipRect: any) -> dict {
    triggerCenter = (triggerRect.left + (triggerRect.width / 2));
    left = (triggerCenter - (tooltipRect.width / 2));
    maxLeft = ((window.innerWidth - tooltipRect.width) - 2);
    return {"left": (Math.min(Math.max(2, left), maxLeft) + window.scrollX), "top": ((triggerRect.bottom + 8) + window.scrollY)};
}

