import os;
import from pathlib { Path }
import from load_env { loadEnv }

def generateIndexNow() {
    print("[SEO] Starting IndexNow key verification file generation...");
    env = loadEnv();
    indexnow_key = env.get("VITE_INDEXNOW_KEY", "");
    if not indexnow_key {
        if os.environ.get("VERCEL") == "1" and os.environ.get("VERCEL_ENV") == "production" {
            raise ValueError("VITE_INDEXNOW_KEY is not defined in the environment. IndexNow verification file generation failed.");
        }
        print("[SEO Warning] VITE_INDEXNOW_KEY is not defined. Skipping IndexNow verification file generation.");
        return;
    }
    public_dir = Path(str(__file__)).resolve().parent.parent / "public";
    key_filename = f"{indexnow_key}.txt";
    key_file_path = public_dir / key_filename;
    info_file_path = public_dir / "indexnow-key.txt";
    key_file_path.write_text(indexnow_key, encoding="utf-8");
    print("[SEO Success] Created IndexNow verification file in public directory.");
    info_file_path.write_text(indexnow_key, encoding="utf-8");
}

with entry {
    try {
        generateIndexNow();
    } except Exception as err {
        print(f"[SEO Error] Failed to generate IndexNow verification files: {err}");
        raise SystemExit(1);
    }
}

