def sliceRange[T](array: list[T] | None = None, fromIndex: int = 0, toIndex: int = 0) -> list[T] {
    arr = array if array is not None else [];
    if fromIndex < toIndex {
        return arr[fromIndex:toIndex + 1];
    }
    return arr[toIndex:fromIndex + 1];
}

glob:pub default = sliceRange;

