async def:pub getSession() -> dict[str, object] | None {
    return None;
}

async def:pub getCurrentUser() -> dict[str, object] | None {
    try {
        session = await getSession();
        if not session {
            return None;
        }
        raw_user = session.get("user");
        if not raw_user {
            return None;
        }
        user = raw_user as dict[str, object];
        if not user.get("email") {
            return None;
        }
        return user;
    } except Exception {
        return None;
    }
}

