import from "lucide-react" { Download, Trash2, Eye, FileText }

def getFileIcon(fileType: str) -> str {
    if fileType.startswith("image/") {
        return "🖼️";
    }
    if (fileType == "application/pdf") {
        return "📄";
    }
    if (((("word" in fileType) or ("document" in fileType)) or (fileType == "text/plain")) or (fileType == "text/markdown")) {
        return "📝";
    }
    if ((("spreadsheet" in fileType) or ("excel" in fileType)) or (fileType == "text/csv")) {
        return "📊";
    }
    if (((("zip" in fileType) or ("tar" in fileType)) or ("rar" in fileType)) or ("gz" in fileType)) {
        return "📦";
    }
    if ((((("javascript" in fileType) or ("typescript" in fileType)) or ("python" in fileType)) or ("java" in fileType)) or ("cpp" in fileType)) {
        return "💻";
    }
    return "📎";
}

