def:pub combineReducers(slices: dict[str, Callable[[object, object], object]]) -> Callable[[dict[str, object], object], dict[str, object]] {
    return lambda (state: dict[str, object], action: object) -> dict[str, object] {
        acc = state;
        for prop in slices {
            acc = {**acc, prop: slices[prop](acc[prop], action)};
        }
        return acc;
    };
}

