# from: Gitmaxd__field-theory-ui::components/sparkline-tooltip.tsx
def:pub SparklineTooltip(
    active: bool = False,
    payload: list[dict[str, float]] | None = None,
    label: str | None = None,
    variant: str = "default",
) -> JsxElement | None {
    if (not active) or (not payload) or (len(payload) == 0) {
        return None;
    }
    value = payload[0]?["value"];
    if value is None {
        return None;
    }

    isObservatory = variant == "observatory";
    label_cls = "text-sm text-foreground" if isObservatory else "text-xs text-muted";
    value_cls = (
        "font-mono text-sm text-foreground"
        if isObservatory
        else "font-mono text-sm font-bold text-foreground"
    );

    return (
        <div className="rounded-card border border-border bg-card px-3 py-2 shadow-lg">
            <p className={label_cls}>{label}</p>
            <p className={value_cls}>{value} bookmarks</p>
        </div>
    );
}

