def:pub getHoneycombPartsUserData(userData: dict[str, object]) -> HoneycombPartsUserData | None {
    value = userData[HONEYCOMB_PARTS_USER_DATA_KEY];
    if not isHoneycombPartsUserData(value) {
        return None;
    }
    return value as HoneycombPartsUserData;
}

def:pub isHoneycombPartsUserData(value: object) -> bool {
    if value is None or not isinstance(value, dict) {
        return False;
    }
    candidate = value as dict[str, object];
    parts = candidate.get("parts");
    return candidate.get("version") == 1 and isinstance(parts, list);
}

