glob cacheio: dict[str, ExtendedUser] = {};

async def:pub getUserProfile(id: str) -> ExtendedUser | None {
    if id in cacheio {
        return cacheio[id];
    }
    try {
        user = await pb.collection("users").getOne(id, {"expand": "blogs(user)"});
        cacheio["profile"] = user as ExtendedUser;
        return user as ExtendedUser;
    } except Exception as err {
        print("Something went wrong" + str(err));
        return None;
    }
}

