def useLazyRef(initialValFunc: any) -> any {
    ref: any = useRef(None);
    if (ref.current == None) {
        ref.current = initialValFunc();
    }
    return ref;
}

def:pub useStore(s: any) -> any {
    store = useLazyRef(s);
    return store.current;
}

