import from "./types.ts" { createWarning }
import from "./registry.ts" { registerRule }
import from "./context.ts" { willChangeIncludes }

type RuleContext = dict[str, dict[str, str]];
type Warning = dict[str, str];
type WarnInput = dict[str, str];
type AnimationProp = dict[str, str];

glob RULE_ID = "animation-no-sub-props";

def warn(fields: WarnInput) -> Warning {
    return createWarning(RULE_ID, fields) as Warning;
}

glob ANIMATION_PROPERTIES: list[AnimationProp] = [{"key": "animationDuration", "cssName": "animation-duration", "defaultValue": "0s"}, {"key": "animationTimingFunction", "cssName": "animation-timing-function", "defaultValue": "ease"}, {"key": "animationDelay", "cssName": "animation-delay", "defaultValue": "0s"}, {"key": "animationIterationCount", "cssName": "animation-iteration-count", "defaultValue": "1"}, {"key": "animationDirection", "cssName": "animation-direction", "defaultValue": "normal"}, {"key": "animationFillMode", "cssName": "animation-fill-mode", "defaultValue": "none"}, {"key": "animationPlayState", "cssName": "animation-play-state", "defaultValue": "running"}];

def hasActiveAnimationName(animationName: str) -> bool {
    for name in [n.strip() for n in animationName.split(",")] {
        if name != "none" and name != "" {
            return True;
        }
    }
    return False;
}

def:pub checkAnimationNoSubProps(ctx: RuleContext) -> list[Warning] {
    styles = ctx["styles"];
    animationName = styles.get("animationName", "none");
    if hasActiveAnimationName(animationName) {
        return [];
    }
    if willChangeIncludes(styles.get("willChange", "auto"), "animation-name", "animation") {
        return [];
    }
    warnings: list[Warning] = [];
    for prop in ANIMATION_PROPERTIES {
        key = prop["key"];
        cssName = prop["cssName"];
        defaultValue = prop["defaultValue"];
        value = styles.get(key, defaultValue);
        if value == defaultValue {
            continue;
        }
        warnings.append(warn({
            "property": cssName,
            "title": f"{cssName} has no effect without animation-name",
            "details": f"{cssName} is \"{value}\" but no animation-name is set. Without an animation-name, no animation runs and this property has no visible effect.",
            "suggestion": "Add an animation-name (e.g. animation-name: fadeIn), or remove the animation property.",
        }));
    }
    return warnings;
}

glob rule: dict[str, object] = {
    "id": RULE_ID,
    "label": "animation properties without animation-name",
    "requiredProperties": ["animationName", "willChange"] + [p["key"] for p in ANIMATION_PROPERTIES],
    "check": checkAnimationNoSubProps,
};

with entry {
    registerRule(rule);
