import from "../../stores/useActivityStore" { useActivityStore }

glob INTENSITY_CLASSES = ["bg-surface-light-elevated dark:bg-surface-dark-elevated", "bg-green-900/40", "bg-green-700/60", "bg-green-500/70", "bg-green-400/80", "bg-green-300"];

def getIntensityClass(count: float, max: float) -> str {
    if (count == 0) {
        return INTENSITY_CLASSES[0];
    }
    if (max == 0) {
        return INTENSITY_CLASSES[0];
    }
    ratio = (count / max);
    if (ratio <= 0.2) {
        return INTENSITY_CLASSES[1];
    }
    if (ratio <= 0.4) {
        return INTENSITY_CLASSES[2];
    }
    if (ratio <= 0.6) {
        return INTENSITY_CLASSES[3];
    }
    if (ratio <= 0.8) {
        return INTENSITY_CLASSES[4];
    }
    return INTENSITY_CLASSES[5];
}

