# from: gusttaswe__react-image-color-picker::util/canvas.tsx
obj Coordinates {
    has x: float;
    has y: float;
}

class Canvas {
    def init(canvas_element: HTMLCanvasElement) {
        self.canvas = canvas_element;
        self.context = self.canvas.getContext("2d", {"willReadFrequently": True}) as CanvasRenderingContext2D;
    }

    def listenMovements(listener: Callable) {
        self.canvas.addEventListener("touchmove", listener);
        self.canvas.addEventListener("pointermove", listener);
    }

    def cleanUp(listener: Callable) {
        self.canvas.removeEventListener("touchmove", listener);
        self.canvas.addEventListener("pointermove", listener);
    }

    def drawImage(img: HTMLImageElement) {
        self.context.drawImage(img, 0, 0);
    }

    def setDimensions(width: int, height: int) {
        self.canvas.width = width;
        self.canvas.height = height;
    }

    def getDimensions -> dict[str, int] {
        return {"width": self.canvas.width, "height": self.canvas.height};
    }

    def getCanvasCenterPoint -> Coordinates {
        return Coordinates(x=self.canvas.width / 2, y=self.canvas.height / 2);
    }

    def getCanvasCoordinates(coordinates: Coordinates) -> Coordinates {
        rect = self.canvas.getBoundingClientRect();
        scale_x = self.canvas.width / rect.width;
        scale_y = self.canvas.height / rect.height;
        x = (coordinates.x - rect.left) * scale_x;
        y = (coordinates.y - rect.top) * scale_y;
        return Coordinates(x=x, y=y);
    }

    def getPixelColor(coordinates: Coordinates) -> str {
        pixel_data = (self.context.getImageData(int(coordinates.x), int(coordinates.y), 1, 1).data) as list[int];
        if len(pixel_data) < 4 {
            return "rgb(0,0,0)";
        }
        red = pixel_data[0];
        green = pixel_data[1];
        blue = pixel_data[2];
        return f"rgb({red}, {green}, {blue})";
    }
}

