def isReasoningEffort(value: object) -> bool {
    return value in ["none", "minimal", "low", "medium", "high", "xhigh"];
}

def:pub toProfile(raw: dict[str, object], activeName: str) -> dict[str, object] {
    name = raw["name"] if isinstance(raw.get("name"), str) else "";
    profile: dict[str, object] = {"name": name, "isActive": name == activeName};
    if isinstance(raw.get("display_name"), str) {
        profile["displayName"] = raw["display_name"];
    }
    if isinstance(raw.get("model"), str) {
        profile["model"] = raw["model"];
    }
    if isinstance(raw.get("provider"), str) {
        profile["provider"] = raw["provider"];
    }
    if isReasoningEffort(raw.get("reasoning_effort")) {
        profile["reasoningEffort"] = raw["reasoning_effort"];
    }
    if isinstance(raw.get("show_reasoning"), bool) {
        profile["showReasoning"] = raw["show_reasoning"];
    }
    if isinstance(raw.get("description"), str) {
        profile["description"] = raw["description"];
    }
    return profile;
}

def:pub toProfileActive(raw: dict[str, object]) -> dict[str, object] {
    return {
        "active": raw["active"] if isinstance(raw.get("active"), str) else None,
        "current": raw["current"] if isinstance(raw.get("current"), str) else None,
    };
}

def:pub toProfileCreateResult(raw: dict[str, object]) -> dict[str, object] {
    result: dict[str, object] = {
        "ok": raw.get("ok") == True,
        "name": raw["name"] if isinstance(raw.get("name"), str) else "",
    };
    if isinstance(raw.get("path"), str) {
        result["path"] = raw["path"];
    }
    if raw.get("model_set") == True {
        result["model_set"] = True;
    }
    return result;
}

