# from: nsdonato__front-invoices::hooks/useEscapeKey.ts
import from "react" { useEffect }

glob KEY_NAME_ESC = "Escape";

glob KEY_EVENT_TYPE = "keydown";

def:pub useEscapeKey(handleClose: Callable[[], None]) {
    useEffect(lambda {
        def handle_esc(event: KeyboardEvent) {
            if event.key == KEY_NAME_ESC {
                handleClose();
            }
        }
        document.addEventListener(KEY_EVENT_TYPE, handle_esc, False);
        return lambda {
            document.removeEventListener(KEY_EVENT_TYPE, handle_esc, False);
        };
    }, [handleClose]);
}

