obj FacetValueState {
    has _onChanged: Callable[[], None],
        value: str,
        count: int,
        _isSelected: bool = False;

    def init(value: str, count: int, onChanged: Callable[[], None], isSelected: bool = False) {
        self._onChanged = onChanged;
        self.value = value;
        self.count = count;
        self._isSelected = isSelected;
    }

    def get_isSelected() -> bool {
        return self._isSelected;
    }

    def set_isSelected(val: bool) {
        self._isSelected = val;
        self._onChanged();
    }

    def unsetSilently() {
        self._isSelected = False;
    }
}

def isValidFacetValue(value: str) -> bool {
    return (len(value) < MaxFacetValueLength)
        and (not re.search(r' {2}|\n|\t', value));
}

def encodeFacetValue(v: str) -> str {
    return quote(v.replace("'", "''"), safe="");
}

def decodeFacetValue(v: str) -> str {
    return unquote(v).replace("''", "'");
}

