        # |         `Extension '${ctx.extensionId}': ` +
        # |           `contributions to point '${contribPointId}' ` +
        # |           `must be given as object, but was ${typeof contrib}.`
        # |       );
        # |     }
        contrib = contrib[contribKey];
        if not contrib {
            return;
        }
    }
    return contrib;
}

